import subprocess,re,json,sys
argv=['xcrun','swiftc','-frontend','-dump-parse','modules/radiant-storekit/ios/RadiantStoreKitModule.swift']
p=subprocess.run(argv,capture_output=True,text=True)
assert p.returncode == 0,p.stderr
# Parse the compiler's AST, never the Swift source (comments are absent here).
tokens=re.findall(r'"(?:\\.|[^"\\])*"|[()]|[^()\s]+',p.stdout+p.stderr)
stack=[]; roots=[]
for token in tokens:
 if token=='(':
  node=[]
  if stack:stack[-1].append(node)
  else:roots.append(node)
  stack.append(node)
 elif token==')':
  if stack:stack.pop()
 elif stack:stack[-1].append(token)
def walk(node):
 if isinstance(node,list):
  yield node
  for child in node:yield from walk(child)
def atoms(node):
 return [v for n in walk(node) for v in n if isinstance(v,str) and (v.startswith('field=') or v.startswith('name=') or v.startswith('label='))]
dictionaries=[n for root in roots for n in walk(root) if n and n[0]=='dictionary_expr']
expected={
 'price':['field="doubleValue"','name="NSDecimalNumber"','label="decimal"','field="price"','name="produto"'],
 'currencyCode':['field="currencyCode"','field="priceFormatStyle"','name="produto"'],
}
results={}
for key,wanted in expected.items():
 matches=[entry for d in dictionaries for entry in d[1:] if isinstance(entry,list) and entry and entry[0]=='tuple_expr' and any(isinstance(child,list) and child and child[0]=='string_literal_expr' and f'value="{key}"' in child for child in entry[1:])]
 assert len(matches)==1, f'{key}: expected one dictionary entry, got {len(matches)}'
 actual=atoms(matches[0]);assert actual==wanted,f'{key}: AST mismatch {actual!r}, expected {wanted!r}'
 results[key]=actual
print(json.dumps({'argv':argv,'parse_exit':p.returncode,'ast_contract':results,'scope':'parse only; no typecheck, build, install or device proof'},ensure_ascii=False))
